#include "helpers.h"

#include <stdio.h>
#include <stdlib.h>


//The two print functions output the requisite data once it traverses the queue generated by the algorithms

void printGanttChart(struct Algorithm* algo) {
    struct QueueNode *currNode = algo->queue->front;
    int timeElapsedCounter = 0;
    int waitingTimeCounter = 0;
    int turnaroundTimeCounter = 0;
    printf("Printing data for %s\n", algo->name);
    printf("Execution order (by pid)\n");


    while (currNode != NULL) {
        struct Process *currProcess = &currNode->process;
        printf(" -- Process: %d -- Waiting Time: %d -- Turnaround Time: %d", currProcess->pid,timeElapsedCounter - currProcess->arrival_time, timeElapsedCounter + currProcess->run_time - currProcess->arrival_time);
        printf("\n");
        turnaroundTimeCounter += (timeElapsedCounter + currProcess->run_time - currProcess->arrival_time);
        waitingTimeCounter += (timeElapsedCounter - currProcess->arrival_time);
        timeElapsedCounter += currProcess->run_time;
        currNode = currNode->next;
    }

    printf("\nAverage waiting time: %.1f", (float) waitingTimeCounter / algo->queue->size);
    printf("\nAverage turnaround time: %.1f", (float) turnaroundTimeCounter / algo->queue->size);
    printf("\n\n");
}

void printPreemptiveGanttChart(struct Algorithm *algo, struct Node *head, int count) {
    struct QueueNode *currNode = algo->queue->front;

    int totalWaitingTime = 0;
    int totalTurnaroundTime = 0;

    printf("\nPrinting data for %s\n", algo->name);
    printf("Execution order (by pid)\n");


    while (currNode != NULL) {
        printf(" -- Process: %d -- Duration: %d\n",
               currNode->process.pid,
               currNode->duration);
        currNode = currNode->next;
    }
    printf("\n\n");

    struct Node *current = head;

    while (current != NULL) {
        struct Process *process = current->process;

        int turnaroundTime = process->turnaround_time;
        int waitingTime = turnaroundTime - process->run_time;

        printf(" -- Process: %d -- Waiting Time: %d -- Turnaround Time: %d\n",
               process->pid,
               waitingTime,
               turnaroundTime);

        totalWaitingTime += waitingTime;
        totalTurnaroundTime += turnaroundTime;

        current = current->next;
    }

    printf("\nAverage waiting time: %.1f",
           (float) totalWaitingTime / count);

    printf("\nAverage turnaround time: %.1f",
           (float) totalTurnaroundTime / count);

    printf("\n\n");
}

//frees the memory of any queue we pass
void freeQueue(struct Queue *queue) {
    struct QueueNode *current = queue->front;
    while (current != NULL) {
        struct QueueNode *next = current->next;
        free(current);
        current = next;
    }
    queue->front = NULL;
    queue->rear = NULL;
    queue->size = 0;
}